     }
     ```

### Full Example

Here's a full example that includes both `term` and `range` queries:

```python
from elasticsearch import Elasticsearch, RequestsHttpConnection
from elasticsearch.exceptions import ElasticsearchException
import logging

# Configure logging
logging.basicConfig(level=logging.ERROR)

es = Elasticsearch(connection_class=RequestsHttpConnection)

def search(index, query, profile=False):
    try:
        response = es.search(index=index, body=query, profile=profile)
        if profile:
            return response['hits']['hits'], response.get('_shards', {}).get('failures'), response.get('profile')
        return response['hits']['hits']
    except ElasticsearchException as e:
        logging.error(f"Error searching: {e}")
        return []

# example usage
index = 'my_index'

# Term query example
term_query = {
    'query': {
        'term': {
            'field_name': 'exact_value'
        }
    },
    'size': 100  # Limit the number of results returned
}

# Range query example
range_query = {
    'query': {
        'range': {
            'numeric_field': {
                'gte': 10,
                'lte': 20
            }
        }
    },
    'size': 100  # Limit the number of results returned
}

# Optionally enable profiling
profile = True

# Perform term query
results_term, shard_failures_term, profile_info_term = search(index, term_query, profile=profile)
print("Term Query Results:", results_term)
if profile:
    print("Term Query Shard Failures:", shard_failures_term)
    print("Term Query Profile Info:", profile_info_term)

# Perform range query
results_range, shard_failures_range, profile_info_range = search(index, range_query, profile=profile)
print("Range Query Results:", results_range)
if profile:
    print("Range Query Shard Failures:", shard_failures_range)
    print("Range Query Profile Info:", profile_info_range)
```

### Summary

By using specific query types like `term` and `range`, you can optimize your Elasticsearch queries for better performance. These query types are designed to match exact terms or ranges, which can significantly reduce the amount of data scanned and processed. Additionally, profiling your queries can help you identify and address any bottlenecks in your query execution.

