import requests

class PagerDutyNotifier:
    def __init__(self, api_token, service_id):
        self.api_token = api_token
        self.service_id = service_id
        self.base_url = 'https://api.pagerduty.com/incidents'

    def trigger_incident(self, summary, details=None):
        headers = {
            'Authorization': f'Token token={self.api_token}',
            'Accept': 'application/vnd.pagerduty+json;version=2',
            'Content-Type': 'application/json'
        }
        data = {
            "incident": {
                "type": "incident",
                "title": summary,
                "service": {"id": self.service_id, "type": "service_reference"},
                "body": {"details": details}
            }
        }
        response = requests.post(self.base_url, headers=headers, json=data)
        if response.status_code != 201:
            raise ValueError(
                f'Request to PagerDuty returned an error {response.status_code}, the response is:\n{response.text}'
            )

