                if 'impact' in feature:
                    notes += f"  Impact: {feature['impact']}\n"
            notes += "\n"

        if self.improvements:
            notes += "Improvements:\n"
            for improvement in self.improvements:
                notes += f"- {improvement['description']}\n"
                if 'impact' in improvement:
                    notes += f"  Impact: {improvement['impact']}\n"
            notes += "\n"

        if self.bug_fixes:
            notes += "Bug Fixes:\n"
            for fix in self.bug_fixes:
                notes += f"- {fix['description']}\n"
                if 'workaround' in fix:
                    notes += f"  Workaround: {fix['workaround']}\n"
            notes += "\n"

        if self.deprecations:
            notes += "Deprecations:\n"
            for deprecation in self.deprecations:
                notes += f"- {deprecation['description']}\n"
                if 'reason' in deprecation:
                    notes += f"  Reason: {deprecation['reason']}\n"
                if 'alternatives' in deprecation:
                    notes += f"  Alternatives: {deprecation['alternatives']}\n"
            notes += "\n"

        if self.known_issues:
            notes += "Known Issues:\n"
            for issue in self.known_issues:
                notes += f"- {issue['description']}\n"
                if 'workaround' in issue:
                    notes += f"  Workaround: {issue['workaround']}\n"
            notes += "\n"

        if self.upgrade_notes:
            notes += "Upgrade Notes:\n"
            for note in self.upgrade_notes:
                notes += f"- {note}\n"
            notes += "\n"

        if self.acknowledgements:
            notes += "Acknowledgements:\n"
            for ack in self.acknowledgements:
                notes += f"- {ack}\n"

        return notes

