import dash
import dash_core_components as dcc
import dash_html_components as html
from dash.dependencies import Input, Output
import plotly.graph_objs as go
import random
import time

# Set up dashboard
app = dash.Dash(__name__)

# Define layout
app.layout = html.Div([
    html.H1("Self-Driving Car Simulation Dashboard"),
    dcc.Tabs(id="tabs", children=[
        dcc.Tab(label="Video Playback Metrics", children=[
            dcc.Graph(id="video-playback-metric"),
            dcc.Interval(id="interval-video-playback", interval=1000)
        ]),
        dcc.Tab(label="System Resource Metrics", children=[
            dcc.Graph(id="cpu-gpu-metric"),
            dcc.Graph(id="memory-metric"),
            dcc.Interval(id="interval-system-resources", interval=1000)
        ])
    ])
])

# Define callback for video playback metrics
@app.callback(Output("video-playback-metric", "figure"), [Input("interval-video-playback", "n_intervals")])
def update_video_playback_metric(n):
    # Fetch metric data
    data = {
        "time": [time.time()],
        "fps": [random.uniform(20, 30)],
        "latency": [random.uniform(0.01, 0.1)]
    }

    # Create figure
    fig = {
        "data": [
            {"x": data["time"], "y": data["fps"], "type": "line", "name": "FPS"},
            {"x": data["time"], "y": data["latency"], "type": "line", "name": "Latency"}
        ],
        "layout": {
            "title": "Video Playback Metrics",
            "xaxis": {"title": "Time"},
            "yaxis": {"title": "Value"}
        }
    }

    return fig

# Define callback for system resource metrics
@app.callback([Output("cpu-gpu-metric", "figure"), Output("memory-metric", "figure")], [Input("interval-system-resources", "n_intervals")])
def update_system_resource_metrics(n):
    # Fetch metric data
    cpu_data = {
        "time": [time.time()],
        "cpu_usage": [random.uniform(20, 80)]
    }
    gpu_data = {
        "time": [time.time()],
        "gpu_usage": [random.uniform(10, 90)]
    }
    memory_data = {
        "time": [time.time()],
        "memory_usage": [random.uniform(500, 1500)]
    }

    # Create CPU/GPU usage figure
    cpu_gpu_fig = {
        "data": [
            {"x": cpu_data["time"], "y": cpu_data["cpu_usage"], "type": "line", "name": "CPU Usage"},
            {"x": gpu_data["time"], "y": gpu_data["gpu_usage"], "type": "line", "name": "GPU Usage"}
        ],
        "layout": {
            "title": "CPU/GPU Usage",
            "xaxis": {"title": "Time"},
            "yaxis": {"title": "Usage (%)"}
        }
    }

    # Create memory usage figure
    memory_fig = {
        "data": [
            {"x": memory_data["time"], "y": memory_data["memory_usage"], "type": "line", "name": "Memory Usage"}
        ],
        "layout": {
            "title": "Memory Usage",
            "xaxis": {"title": "Time"},
            "yaxis": {"title": "Memory (MB)"}
        }
    }

    return cpu_gpu_fig, memory_fig

# Run dashboard
if __name__ == "__main__":
    app.run_server(debug=True)
```

### Explanation

